      app2(
        Checkbox(
          value: false,
          indeterminate: true,
          semanticLabel: 'All',
          onChanged: (v) => value = v,
        ),
      ),
    );
    expect(
      tester
          .getSemantics(find.bySemanticsLabel('All'))
