    );
    expect(
      tester
          .getSemantics(find.text('County'))
          .getSemanticsData()
          .flagsCollection
          .isHeader,
      isTrue,
    );
    expect(find.text('Lagos'), findsOneWidget);
    semantics.dispose();
  });
}
