class ChartAnnotation<T> extends ChartPart<T> {
  const ChartAnnotation({
    required this.x,
    required this.y,
    required this.child,
    this.yAxisId = '',
    this.alignment = Alignment.bottomCenter,
  });

  final Object x;
  final num y;
  final String yAxisId;
