typedef _Day = ({DateTime day, double open, double high, double low, double close});

final _days = () {
  final out = <_Day>[];
  var p = 100.0;
  for (var i = 0; i < 60; i++) {
    // A steady walk with a wave in it, the same every time.
    final c = p + ((i * 37) % 11 - 5) * .6 + (i % 20 < 10 ? .4 : -.4);
    out.add((
      day: DateTime(2026, 1, 1).add(Duration(days: i)),
      open: p,
      high: (p > c ? p : c) + 1.2,
      low: (p < c ? p : c) - 1.2,
      close: c,
    ));
    p = c;
  }
  return out;
}();

