/// The day from opening to closing, a column for each of [staff], their bookings placed
/// at their hours.
class _Day extends StatelessWidget {
  const _Day({required this.staff});

  final List<String> staff;

  static const _open = 9, _close = 18, _hour = 64.0;

  static String _time(double h) {
    final hour = h.floor();
    final minutes = ((h - hour) * 60).round();
    final twelve = hour > 12 ? hour - 12 : hour;
    return '$twelve${minutes == 0 ? '' : ':${minutes.toString().padLeft(2, '0')}'}${hour < 12 ? 'am' : 'pm'}';
  }

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    const gutter = 52.0;
    return SingleChildScrollView(
      padding: const EdgeInsets.fromLTRB(8, 8, 16, 24),
      child: Column(
        children: [
          // Who each column is.
          Row(
            children: [
              const SizedBox(width: gutter),
              for (final name in staff)
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.symmetric(vertical: 8),
                    child: Text(
                      name,
                      textAlign: TextAlign.center,
                      style: t.text.sm.copyWith(fontWeight: FontWeight.w500),
                    ),
                  ),
                ),
            ],
          ),
          SizedBox(
            height: (_close - _open) * _hour,
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                SizedBox(
                  width: gutter,
                  child: Stack(
                    children: [
                      for (var h = _open; h < _close; h++)
                        Positioned(
                          top: h == _open ? 0 : (h - _open) * _hour - 7,
                          right: 8,
                          child: Text(
                            _time(h.toDouble()),
                            style: t.text.xs.copyWith(color: c.mutedForeground),
                          ),
                        ),
                    ],
                  ),
                ),
                for (final name in staff)
                  Expanded(
                    child: Container(
                      decoration: BoxDecoration(
                        border: BorderDirectional(
                          start: BorderSide(color: c.border),
                        ),
                      ),
                      child: Stack(
                        children: [
                          for (var h = 0; h < _close - _open; h++)
                            Positioned(
                              top: h * _hour,
                              left: 0,
                              right: 0,
                              child: Container(height: 1, color: c.border),
                            ),
                          for (final (who, from, length, client, service)
                              in _bookings)
                            if (who == name)
                              Positioned(
                                top: (from - _open) * _hour + 2,
                                height: length * _hour - 4,
                                left: 4,
                                right: 4,
                                child: Container(
                                  padding: const EdgeInsets.all(6),
                                  clipBehavior: Clip.antiAlias,
                                  decoration: BoxDecoration(
                                    color: c.secondary,
                                    borderRadius: BorderRadius.circular(
                                      t.radiusMd,
                                    ),
                                    border: BorderDirectional(
                                      start: BorderSide(
                                        color: c.primary,
                                        width: 3,
                                      ),
                                    ),
                                  ),
                                  // An hour or more has room for two lines;
                                  // a shorter one says it all on one.
                                  child: length >= 1
                                      ? Column(
                                          crossAxisAlignment:
                                              CrossAxisAlignment.start,
                                          children: [
                                            Text(
                                              client,
                                              maxLines: 1,
                                              overflow: TextOverflow.ellipsis,
                                              style: t.text.xs.copyWith(
                                                fontWeight: FontWeight.w600,
                                                color: c.secondaryForeground,
                                              ),
                                            ),
                                            Text(
                                              '$service, ${_time(from)}',
                                              maxLines: 2,
                                              overflow: TextOverflow.ellipsis,
                                              style: t.text.xs.copyWith(
                                                color: c.mutedForeground,
                                              ),
                                            ),
                                          ],
                                        )
                                      : Text.rich(
                                          TextSpan(
                                            children: [
                                              TextSpan(
                                                text: client,
                                                style: TextStyle(
                                                  fontWeight: FontWeight.w600,
                                                  color: c.secondaryForeground,
                                                ),
                                              ),
                                              TextSpan(
                                                text:
                                                    '  $service, ${_time(from)}',
                                              ),
                                            ],
                                          ),
                                          maxLines: 1,
                                          overflow: TextOverflow.ellipsis,
                                          style: t.text.xs.copyWith(
                                            color: c.mutedForeground,
                                          ),
                                        ),
                                ),
                              ),
                        ],
                      ),
                    ),
                  ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}
''',
    },
  ),
  'shop-settings': Component(
