/// A sign-in page beside a picture or a customer's word.
class SplitSignIn extends StatefulWidget {
  const SplitSignIn({
    super.key,
    this.picture,
    this.onSignIn,
    this.onForgot,
    this.onCreate,
    this.onGoogle,
  });

