          ),
          const SizedBox(height: 16),
          FormText(
            label: const Text('Email for statements'),
            placeholder: 'accounts@example.com',
            keyboardType: TextInputType.emailAddress,
            validator: Validate.all([
              Validate.required('Enter an email.'),
              Validate.email(),
            ]),
            onSaved: (v) => _email = v!,
          ),
          const SizedBox(height: 24),
          Button(
            expand: true,
            onPressed: _send,
            child: const Text('Open the account'),
          ),
          const SizedBox(height: 12),
          Wrap(
            spacing: 6,
            alignment: WrapAlignment.center,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              const Text('Already with us?'),
              Button(
                variant: ButtonVariant.link,
                onPressed: () => widget.onSignIn?.call(),
                child: const Text('Sign in'),
              ),
            ],
          ),
        ],
      ),
    );
    final page = Center(
      child: SingleChildScrollView(
        padding: const EdgeInsets.all(24),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 400),
          child: form,
        ),
      ),
    );
    return LayoutBuilder(
      builder: (context, box) => box.maxWidth < 900
          ? page
          : Row(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                SizedBox(
                  width: box.maxWidth * .42,
                  child: ColoredBox(
                    color: c.muted,
                    child: Padding(
                      padding: const EdgeInsets.all(48),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Row(
                            children: [
                              const AshlarIcon(
                                AshlarIconsRoundedStroke.store,
                                size: 20,
                              ),
                              const SizedBox(width: 8),
                              Text(
                                'Tally Books',
                                style: t.text.base.copyWith(
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
