  final VoidCallback? onSend, onRequest, onPay, onTopUp;
  final ValueChanged<WalletEntry>? onEntry;
  final VoidCallback? onSeeAll;

  @override
  State<Wallet> createState() => _WalletState();
}

const _entries = [
  WalletEntry('Maya Thompson', 'Sent to you', 'Today, 10:42', 250),
  WalletEntry(
    'City Power & Light',
    'Bill, account 4410 2201',
    'Today, 08:15',
    -86,
  ),
  WalletEntry('Corner Pantry', 'Groceries', 'Yesterday, 18:30', -64.2),
  WalletEntry('Otieno Mwangi', 'You sent', 'Yesterday, 12:05', -100),
  WalletEntry('Salary', 'Mittolabs', '20 October', 4200),
];

/// 24350 as "24,350.00".
String _money(double v) {
  final whole = v.abs().truncate().toString();
  final cents = ((v.abs() - v.abs().truncate()) * 100)
      .round()
      .toString()
      .padLeft(2, '0');
  final grouped = whole.replaceAllMapped(
    RegExp(r'\B(?=(\d{3})+(?!\d))'),
    (_) => ',',
  );
  return '$grouped.$cents';
}

